import { FixtureWarmupQuestion } from '../fixtures/hyrte-fixture.types';

/**
 * Founder feedback (WhatsApp, 9 Sep): "I've noticed some questions are very
 * repeated in pm role, bakio me bhi honge — isse fix kro. Kuch bhi repeat nhi
 * hona chahiye."
 *
 * The baseline warm-up questions were generated by one LLM call per session
 * whose only variety input was a random 6-char nonce. That is not enough: ask
 * any model for "warm-up questions for a Product Manager" and it converges on
 * the same handful of canonical questions (validate a feature idea, prioritize
 * a roadmap, define success metrics) no matter what nonce you attach — exactly
 * the repetition that was observed. `priorWarmupQuestions` existed as an
 * avoid-list but was only ever populated for ASSESSMENT sessions launched from
 * a recruiter link; self-serve PRACTICE sessions (which is what the founder was
 * running) passed no grounding at all, so nothing suppressed repeats there.
 *
 * This module is the deterministic half of the fix — the same discipline used
 * elsewhere in this codebase (hiddenIntention omission, EVn-label stripping,
 * repetition detection): don't rely on the LLM noticing it is repeating itself.
 *
 *  1. `pickAxes` hands the generator an explicit, rotated set of competency
 *     axes to write questions about — different axes per session, walked
 *     round-robin off the candidate's own prior-session count, so two
 *     consecutive sessions in the same role cannot even be asked to cover the
 *     same ground.
 *  2. `enforceWarmupVariety` runs AFTER generation and drops anything that is
 *     still a near-duplicate (of a prior session's question or of a sibling in
 *     the same set), backfilling from a real per-axis question bank rather than
 *     shipping the duplicate.
 */

export interface RoleAxisPool {
  /** Named competency sub-topics for this role family. */
  axes: string[];
  /** One real, usable question per axis — the deterministic backfill when generation repeats itself. */
  bank: Record<string, string[]>;
}

