export function resolveAxisPool(role: string): RoleAxisPool {
  return ROLE_AXIS_POOLS.find((entry) => entry.pattern.test(role))?.pool ?? GENERIC_POOL;
}

/**
 * Deterministic rotation: session N for a given candidate+role starts at a
 * different offset in the pool than session N-1, so consecutive sessions
 * cannot be asked to cover the same competencies at all. `priorSessionCount`
 * is the candidate's own real count of prior sessions in this role.
 */
export function pickAxes(role: string, count: number, priorSessionCount: number): string[] {
  const { axes } = resolveAxisPool(role);
  const start = (priorSessionCount * count) % axes.length;
  return Array.from({ length: Math.min(count, axes.length) }, (_, i) => axes[(start + i) % axes.length]);
}

/**
 * Question wording varies in ways that carry no meaning — "prioritise" vs
 * "prioritize", "your roadmap" vs "the roadmap", "is urgent" vs "feels
 * urgent". Raw Jaccard over every word (what the interview's own
 * answer-repetition detector does) scores that pair at 0.54 and lets the
 * reword through, which is precisely the "lightly reworded repeat" the
 * founder flagged. Comparing CONTENT words only — stopwords dropped, spelling
 * and plurals normalized — scores the same pair at 1.0.
 */
const STOPWORDS = new Set([
  'a', 'an', 'and', 'are', 'as', 'at', 'be', 'been', 'but', 'by', 'can', 'could', 'did', 'do', 'does', 'for',
  'from', 'had', 'has', 'have', 'how', 'i', 'if', 'in', 'into', 'is', 'it', 'its', 'just', 'me', 'my', 'of',
  'on', 'or', 'our', 'out', 'over', 'should', 'so', 'some', 'something', 'than', 'that', 'the', 'their',
  'them', 'then', 'there', 'these', 'they', 'this', 'to', 'up', 'was', 'we', 'were', 'what', 'when', 'which',
  'while', 'who', 'why', 'will', 'with', 'would', 'you', 'your', 'yours',
]);

function contentWords(text: string): Set<string> {
  return new Set(
    text
      .toLowerCase()
      .split(/\W+/)
      .filter(Boolean)
      .map((w) => w.replace(/(is|iz)(e|ed|es|ing|ation)$/, 'ize').replace(/(ies|es|s)$/, ''))
      .filter((w) => w.length > 2 && !STOPWORDS.has(w)),
  );
}

/** Jaccard over content words — deterministic, no LLM call. */
export function questionSimilarity(a: string, b: string): number {
  const setA = contentWords(a);
  const setB = contentWords(b);
  if (setA.size === 0 || setB.size === 0) return 0;
  let intersection = 0;
  for (const word of setA) if (setB.has(word)) intersection++;
  const union = setA.size + setB.size - intersection;
  return union === 0 ? 0 : intersection / union;
}

const DUPLICATE_THRESHOLD = 0.5;

function isDuplicate(question: string, against: string[]): boolean {
  return against.some((other) => questionSimilarity(question, other) >= DUPLICATE_THRESHOLD);
}

/**
 * The deterministic guarantee behind "kuch bhi repeat nhi hona chahiye": any
 * generated question that is a near-duplicate of one this candidate already
 * saw in this role — or of a sibling in the same set — is dropped and replaced
 * from the axis bank. Runs after generation, so it holds even when the model
 * ignores both the axis list and the avoid-list in the prompt.
 *
 * Returns exactly `expectedCount` questions whenever the bank can supply them.
 */
export function enforceWarmupVariety(
  questions: FixtureWarmupQuestion[],
  role: string,
  priorQuestions: string[],
  axes: string[],
  expectedCount: number,
): FixtureWarmupQuestion[] {
  const pool = resolveAxisPool(role);
  const kept: FixtureWarmupQuestion[] = [];
  const seen = [...priorQuestions];

  for (const q of questions) {
    if (kept.length >= expectedCount) break;
    if (isDuplicate(q.question, seen)) continue;
    kept.push(q);
    seen.push(q.question);
  }

  if (kept.length >= expectedCount) return kept;

  // Backfill from the bank, preferring this session's own assigned axes and
  // skipping any bank entry that is itself a near-duplicate of what the
  // candidate has already been asked.
  const orderedAxes = [...axes, ...pool.axes.filter((a) => !axes.includes(a))];
  for (const axis of orderedAxes) {
    for (const candidate of pool.bank[axis] ?? []) {
      if (kept.length >= expectedCount) return kept;
      if (isDuplicate(candidate, seen)) continue;
      kept.push({ id: `wq-${axis.replace(/[^a-z]+/gi, '-').toLowerCase()}-${kept.length + 1}`, question: candidate });
      seen.push(candidate);
    }
  }
  return kept;
}
